bool PhysicsWorld3D::DestroyBody(RigidBodyHandle3D handle){const bool destroyed=bodies_.erase(handle.value)>0;broadPhaseDirty_|=destroyed;return destroyed;}
void PhysicsWorld3D::Clear(){std::unordered_map<uint32_t,RigidBodyState3D>{}.swap(bodies_);std::vector<RigidBodyState3D*>{}.swap(broadPhaseObstacles_);std::vector<RigidBodyState3D*>{}.swap(broadPhaseDynamicBodies_);stats_={};maximumObstacleHalfWidth_=0;broadPhaseDirty_=true;lastReleasedBytes_=0;trimCount_=0;}
RigidBodyState3D* PhysicsWorld3D::FindBody(RigidBodyHandle3D handle){const auto found=bodies_.find(handle.value);return found==bodies_.end()?nullptr:&found->second;}
RigidBodyState3D* PhysicsWorld3D::GetBody(RigidBodyHandle3D handle){RigidBodyState3D* body=FindBody(handle);broadPhaseDirty_|=body!=nullptr;return body;}
const RigidBodyState3D* PhysicsWorld3D::GetBody(RigidBodyHandle3D handle)const{const auto found=bodies_.find(handle.value);return found==bodies_.end()?nullptr:&found->second;}
