bool PhysicsWorld3D::SetVelocity(RigidBodyHandle3D handle,Vec3 velocity){RigidBodyState3D* body=FindBody(handle);if(!body||body->settings.type==RigidBodyType3D::Static)return false;body->velocity=velocity;body->sleeping=false;body->sleepClock=0;return true;}
bool PhysicsWorld3D::AddForce(RigidBodyHandle3D handle,Vec3 force){RigidBodyState3D* body=FindBody(handle);if(!body||body->settings.type!=RigidBodyType3D::Dynamic)return false;body->accumulatedForce=body->accumulatedForce+force;body->sleeping=false;return true;}
